fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 16 * 16);
        host::display::state_set(2, 0);
    }
    let mut y: i32 = host::display::state_get(1);
    let mut vy: i32 = host::display::state_get(2);
    vy = vy + 3;
    y = y + vy;
    let floor: i32 = (h - 18) * 16;
    if y > floor {
        y = floor;
        vy = (0 - vy) * 3 / 4;
    }
    host::display::state_set(1, y);
    host::display::state_set(2, vy);
    host::display::clear(0x000000);
    host::display::fill_rect(0, h - 2, w, 2, 0x404040);
    host::display::fill_rect(w / 2 - 8, y / 16, 16, 16, 0x00ff66);
    host::display::present();
}
